const input = $input.first().json;
let jdText = "";
let source = "unknown";
if (input.message && input.message.text) {
  jdText = input.message.text.trim();
  source = "telegram";
} else if (input.body && input.body.jd_text) {
  jdText = input.body.jd_text;
  source = "webhook";
} else if (input.timestamp) {
  jdText = input.jd_text || "Placeholder JD for scheduled scan";
  source = "cron";
}
return [{ json: { jd_text: jdText, source: source, received_at: new Date().toISOString() } }];

const raw = typeof $json.data === "string" ? $json.data : JSON.stringify($json.data || "");
let text = "";
let inTag = false;
for (let i = 0; i < raw.length; i++) {
  if (raw[i] === "<") { inTag = true; continue; }
  if (raw[i] === ">") { inTag = false; continue; }
  if (!inTag) text += raw[i];
}
text = text.replace(/\s+/g, " ").trim().slice(0, 8000);
const src = $("Code in JavaScript").item.json.source;
const ts = $("Code in JavaScript").item.json.received_at;
return [{ json: { jd_text: text, source: src, received_at: ts } }];

const raw = $json.text || "";
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");
if (start === -1 || end === -1) throw new Error("No JSON found: " + raw.slice(0, 100));
return [{ json: JSON.parse(raw.slice(start, end + 1)) }];

