parameters.jsCode:
const text = $json.text || "";
const maxLen = 4000;
const items = [];
let start = 0;
while (start < text.length) {
  items.push({ json: { chunk: text.slice(start, start + maxLen) } });
  start += maxLen;
}
return items.length > 0 ? items : [{ json: { chunk: "(No interview prep generated)" } }];

